mapper.select:
select f.id as favoriteId, f.goods_id as goodsId, g.id as id, g.seller_id as sellerId, u.name as sellerName, g.category_id as categoryId, c.name as categoryName, g.title, g.price, g.old_price as oldPrice, g.quality, g.location, g.status, as statusDesc, g.cover, g.favorite_count as favoriteCount, f.create_time as favoriteTime from favorite f left join goods g on f.goods_id = g.id left join user u on g.seller_id = u.id left join category c on g.category_id = c.id where f.user_id = #{userId}
order by f.create_time asc, f.id asc
order by f.create_time desc, f.id desc
